const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const rosettaPoint = ee.Geometry.Point([30.6, 31.5]); // Rosetta branch coordinates
  const region = rosettaPoint.buffer(5000); // 5km buffer around the point

  const start1984 = '1984-01-01';
  const end1984 = '1984-12-31';
  const start2021 = '2021-01-01';
  const end2021 = '2021-12-31';

  // Function to mask clouds for Landsat
  function maskLandsatClouds(image) {
    const qa = image.select('QA_PIXEL');
    const cloudBitMask = 1 << 3;
    const shadowBitMask = 1 << 4;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(shadowBitMask).eq(0));
    return image.updateMask(mask);
  }

  // 2. Data Acquisition for 1984 (Landsat 5)
  let landsat5 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterDate(start1984, end1984)
    .filterBounds(region)
    .map(maskLandsatClouds);

  let landsat5Count = landsat5.size().getInfo();

  // If no Landsat 5, try fallback
  if (landsat5Count === 0) {
    landsat5 = ee.ImageCollection('LANDSAT/LT04/C02/T1_L2')
      .filterDate(start1984, end1984)
      .filterBounds(region)
      .map(maskLandsatClouds);
    landsat5Count = landsat5.size().getInfo();
  }

  // Data Acquisition for 2021 (Landsat 8)
  let landsat8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterDate(start2021, end2021)
    .filterBounds(region)
    .map(maskLandsatClouds);

  let landsat8Count = landsat8.size().getInfo();

  // Check for empty collections
  if (landsat5Count === 0 || landsat8Count === 0) {
    print(`1984 Images: ${landsat5Count}, 2021 Images: ${landsat8Count}`);
    print("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate NDVI
  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['SR_B4', 'SR_B3']).rename('NDVI');
    return image.addBands(ndvi);
  }

  const ndvi1984 = landsat5.map(addNDVI).select('NDVI').median();
  const ndvi2021 = landsat8.map(addNDVI).select('NDVI').median();

  // 4. Calculate statistics and check valid pixels
  const stats1984 = ndvi1984.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const stats2021 = ndvi2021.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const mean1984 = stats1984.NDVI_mean;
  const mean2021 = stats2021.NDVI_mean;
  const count1984 = stats1984.NDVI_count;
  const count2021 = stats2021.NDVI_count;

  // Check for no valid pixels
  if (count1984 === 0 || count2021 === 0) {
    print(`1984 Pixels: ${count1984}, 2021 Pixels: ${count2021}`);
    print("<answer>C2</answer>");
    return;
  }

  // 5. Validation & Final Answer
  print(`1984 NDVI: ${mean1984?.toFixed(3)}, Pixels: ${count1984}`);
  print(`2021 NDVI: ${mean2021?.toFixed(3)}, Pixels: ${count2021}`);

  // Check for calculation failure
  if (mean1984 === null || mean2021 === null || 
      isNaN(mean1984) || isNaN(mean2021) ||
      Math.abs(mean1984) > 1 || Math.abs(mean2021) > 1) {
    print("<answer>C3</answer>");
    return;
  }

  // Determine final answer
  if (mean1984 > mean2021) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
